    public static void render(PoseStack poseStack, VertexConsumer consumer,
                              int packedLight, int packedOverlay, int argb) {
        PoseStack.Pose pose = poseStack.last();
        Matrix4f poseMatrix = pose.pose();
        Matrix3f normalMatrix = pose.normal();
        float red = ((argb >> 16) & 0xFF) / 255.0F;
        float green = ((argb >> 8) & 0xFF) / 255.0F;
        float blue = (argb & 0xFF) / 255.0F;
        float alpha = ((argb >>> 24) & 0xFF) / 255.0F;

        for (float[] face : FACES) {
            float ax = face[3] - face[0];
            float ay = face[4] - face[1];
            float az = face[5] - face[2];
            float bx = face[6] - face[0];
            float by = face[7] - face[1];
            float bz = face[8] - face[2];
            float nx = ay * bz - az * by;
            float ny = az * bx - ax * bz;
            float nz = ax * by - ay * bx;
            float length = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
            if (length > 1.0E-6F) { nx /= length; ny /= length; nz /= length; }

            for (int i = 0; i < 4; i++) {
                int p = i * 3;
                int t = 12 + i * 2;
                consumer.vertex(poseMatrix, face[p], face[p + 1], face[p + 2])
                        .color(red, green, blue, alpha)
                        .uv(face[t], face[t + 1])
                        .overlayCoords(packedOverlay)
                        .uv2(packedLight)
                        .normal(normalMatrix, nx, ny, nz)
                        .endVertex();
            }
        }
    }
